## Automated AI review

> **Community review:** Independent automated community review, unaffiliated with the Omarchy team, intended to help prepare PRs for their review.

**Outcome:** A clipboard read does not use up a Wayland selection, so this drops image history without a demonstrated cause.

### The single-use pipe premise does not reproduce

Hyprland forwards each read to the owner; `wl-copy` 2.3.0 and Chromium answer each on its own fd. With the removed watcher, 15 of 15 pastes over 5 copies were identical and `wl-copy` never stuck. **Impact:** new image copies go unrecorded; the hang stays unexplained.

**Suggested change:** Share `ps -eo pid,ppid,etime,args` output from a hang; if `capture.sh` is stalled, bounding its reads (open #9488) keeps image history.

<details><summary>Reproducer (premise, at 03a253c2)</summary>

Checks the PR's premise with the image watcher the PR removes (the two watcher commands are copied from `Clipboard.qml` at the merge base, lines 285 and 294). `capture.sh` is unchanged by the PR. The script uses the real `wl-copy`/`wl-paste` (wl-clipboard 2.3.0, the version Arch ships) on a private Wayland display (`relay.c`). That display only implements `wl_seat` and `ext-data-control`, and it forwards every read to the clipboard owner, as Hyprland does (`src/protocols/ExtDataDevice.cpp`, lines 14-29 at v0.56.2). Your session clipboard is not touched.

The watcher reads the 3 MiB image first, then three pastes each still get identical bytes, and `wl-copy` keeps serving. The last line shows that the shell-start snapshot (`currentProc`, which the PR keeps) still records the current image.

Run: put `relay.c` and `repro.sh` in one directory, then `OMARCHY=/path/to/omarchy-checkout bash repro.sh` (needs wl-clipboard, gcc, pkg-config, wayland-scanner, wayland-protocols, the libwayland development files, jq, perl, setpriv).

## relay.c

```c
// Minimal Wayland display with only wl_seat and ext-data-control, relaying
// clipboard reads the way wlroots/Hyprland do: each offer.receive(mime, fd)
// becomes source.send(mime, fd). Logs one line per relayed read to stderr.
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <wayland-server.h>
#include "ext-data-control-v1-server-protocol.h"

struct source { struct wl_resource *res; struct wl_array mimes; };
struct offer { struct source *src; struct wl_list link; };
struct device { struct wl_resource *res; struct wl_list link; };
static struct wl_list devices, offers;
static struct source *selection;

static void offer_receive(struct wl_client *c, struct wl_resource *r, const char *mime, int32_t fd) {
  struct offer *o = wl_resource_get_user_data(r);
  if (o->src && o->src == selection) {
    fprintf(stderr, "relay: read of %s forwarded to the source\n", mime);
    ext_data_control_source_v1_send_send(o->src->res, mime, fd);
  }
  close(fd);
}
static void destroy_req(struct wl_client *c, struct wl_resource *r) { wl_resource_destroy(r); }
static const struct ext_data_control_offer_v1_interface offer_impl = {offer_receive, destroy_req};
static void offer_gone(struct wl_resource *r) {
  struct offer *o = wl_resource_get_user_data(r);
  wl_list_remove(&o->link);
  free(o);
}

static void send_selection(struct device *d) {
  if (!selection) { ext_data_control_device_v1_send_selection(d->res, NULL); return; }
  struct wl_resource *or = wl_resource_create(wl_resource_get_client(d->res), &ext_data_control_offer_v1_interface, 1, 0);
  struct offer *o = calloc(1, sizeof *o);
  o->src = selection;
  wl_list_insert(&offers, &o->link);
  wl_resource_set_implementation(or, &offer_impl, o, offer_gone);
  ext_data_control_device_v1_send_data_offer(d->res, or);
  char **m;
  wl_array_for_each(m, &selection->mimes) ext_data_control_offer_v1_send_offer(or, *m);
  ext_data_control_device_v1_send_selection(d->res, or);
}
static void broadcast(void) { struct device *d; wl_list_for_each(d, &devices, link) send_selection(d); }

static void set_selection(struct wl_client *c, struct wl_resource *r, struct wl_resource *sr) {
  struct source *s = sr ? wl_resource_get_user_data(sr) : NULL, *old = selection;
  if (s == old) return;
  selection = s;
  if (old) ext_data_control_source_v1_send_cancelled(old->res);
  broadcast();
}
static void set_primary(struct wl_client *c, struct wl_resource *r, struct wl_resource *sr) {}
static const struct ext_data_control_device_v1_interface device_impl = {set_selection, destroy_req, set_primary};
static void device_gone(struct wl_resource *r) {
  struct device *d = wl_resource_get_user_data(r);
  wl_list_remove(&d->link);
  free(d);
}

static void source_offer(struct wl_client *c, struct wl_resource *r, const char *mime) {
  struct source *s = wl_resource_get_user_data(r);
  *(char **)wl_array_add(&s->mimes, sizeof(char *)) = strdup(mime);
}
static const struct ext_data_control_source_v1_interface source_impl = {source_offer, destroy_req};
static void source_gone(struct wl_resource *r) {
  struct source *s = wl_resource_get_user_data(r);
  struct offer *o;
  wl_list_for_each(o, &offers, link) if (o->src == s) o->src = NULL;
  if (selection == s) { selection = NULL; broadcast(); }
  char **m;
  wl_array_for_each(m, &s->mimes) free(*m);
  wl_array_release(&s->mimes);
  free(s);
}

static void create_source(struct wl_client *c, struct wl_resource *r, uint32_t id) {
  struct source *s = calloc(1, sizeof *s);
  wl_array_init(&s->mimes);
  s->res = wl_resource_create(c, &ext_data_control_source_v1_interface, 1, id);
  wl_resource_set_implementation(s->res, &source_impl, s, source_gone);
}
static void get_device(struct wl_client *c, struct wl_resource *r, uint32_t id, struct wl_resource *seat) {
  struct device *d = calloc(1, sizeof *d);
  d->res = wl_resource_create(c, &ext_data_control_device_v1_interface, 1, id);
  wl_resource_set_implementation(d->res, &device_impl, d, device_gone);
  wl_list_insert(&devices, &d->link);
  send_selection(d);
}
static const struct ext_data_control_manager_v1_interface manager_impl = {create_source, get_device, destroy_req};
static void bind_manager(struct wl_client *c, void *data, uint32_t v, uint32_t id) {
  wl_resource_set_implementation(wl_resource_create(c, &ext_data_control_manager_v1_interface, 1, id), &manager_impl, NULL, NULL);
}
static void bind_seat(struct wl_client *c, void *data, uint32_t v, uint32_t id) {
  struct wl_resource *r = wl_resource_create(c, &wl_seat_interface, v, id);
  wl_resource_set_implementation(r, NULL, NULL, NULL);
  wl_seat_send_capabilities(r, 0);
  wl_seat_send_name(r, "seat0");
}
static int quit(int sig, void *dpy) { wl_display_terminate(dpy); return 0; }

int main(void) {
  signal(SIGPIPE, SIG_IGN);
  wl_list_init(&devices);
  wl_list_init(&offers);
  struct wl_display *dpy = wl_display_create();
  const char *name = wl_display_add_socket_auto(dpy);
  wl_global_create(dpy, &wl_seat_interface, 2, NULL, bind_seat);
  wl_global_create(dpy, &ext_data_control_manager_v1_interface, 1, NULL, bind_manager);
  wl_event_loop_add_signal(wl_display_get_event_loop(dpy), SIGTERM, quit, dpy);
  printf("%s\n", name);
  fflush(stdout);
  wl_display_run(dpy);
  wl_display_destroy_clients(dpy);
  wl_display_destroy(dpy);
  return 0;
}
```

## repro.sh

```bash
#!/bin/bash
# Does the image watcher that PR #11715 removes stop a paste from getting an image?
# Usage: OMARCHY=/path/to/omarchy/checkout bash repro.sh   (needs relay.c next to it)
# Needs wl-clipboard, gcc, wayland-scanner, wayland-protocols, jq, perl, setpriv.
# Everything runs on a private Wayland display; the session clipboard is not touched.
set -u
here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
pids=()
trap 'kill "${pids[@]}" 2>/dev/null; wait 2>/dev/null; rm -rf "$work"' EXIT
export XDG_RUNTIME_DIR=$work HOME=$work/home XDG_STATE_HOME=$work/state
mkdir -p "$HOME" "$XDG_STATE_HOME"

xml=$(pkg-config --variable=pkgdatadir wayland-protocols)/staging/ext-data-control/ext-data-control-v1.xml
wayland-scanner server-header "$xml" "$work/ext-data-control-v1-server-protocol.h"
wayland-scanner private-code "$xml" "$work/ext-data-control-v1-protocol.c"
gcc -I"$work" -o "$work/relay" "$here/relay.c" "$work/ext-data-control-v1-protocol.c" -lwayland-server || exit 1

"$work/relay" >"$work/display" 2>"$work/relay.log" &
pids+=($!)
until [[ -s $work/display ]]; do sleep 0.05; done
export WAYLAND_DISPLAY=$(<"$work/display")

# The two watchers as Clipboard.qml declares them before the PR.
capture=$OMARCHY/shell/plugins/clipboard/capture.sh
setpriv --pdeathsig TERM wl-paste --type text --watch "$capture" text >"$work/text-watcher.out" &
pids+=($!)
setpriv --pdeathsig TERM wl-paste --type image/png --watch "$capture" image/png >"$work/image-watcher.out" &
pids+=($!)
sleep 1

{ printf '\x89PNG\r\n\x1a\n'; head -c 3145728 /dev/urandom; } >"$work/image.png"
wl-copy --foreground --type image/png <"$work/image.png" &
copy_pid=$!
pids+=($copy_pid)

for _ in $(seq 1 100); do [[ -s $work/image-watcher.out ]] && break; sleep 0.05; done
echo "image watcher recorded: $(jq -c '{type, mime}' "$work/image-watcher.out")"
cmp -s "$(jq -r .path "$work/image-watcher.out")" "$work/image.png" && echo "image watcher's stored copy is identical"

for i in 1 2 3; do
  if timeout 5 wl-paste --type image/png | cmp -s - "$work/image.png"; then
    echo "paste $i after the watcher's read: identical $(stat -c %s "$work/image.png") bytes"
  else
    echo "paste $i after the watcher's read: DIFFERENT or empty"
  fi
done
kill -0 "$copy_pid" 2>/dev/null && echo "wl-copy is still serving the image"
echo "reads the source served:"
sed 's/^/  /' "$work/relay.log"

# Shell start runs capture.sh with no arguments (currentProc), which the PR keeps.
echo "startup snapshot at the PR head records: $("$capture" | jq -c '{type, mime}')"
```

