## source.c

```c
// A clipboard owner shaped like Chromium's "Copy image": it offers image/png,
// text/html (<img> markup) and text/x-moz-url, serves every read separately
// from memory on a forked writer, and logs each read to stderr.
// Usage: source IMAGEFILE   (prints "ready" once it owns the selection)
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <wayland-client.h>
#include "ext-data-control-v1-client-protocol.h"

static struct wl_seat *seat;
static struct ext_data_control_manager_v1 *manager;
static char image[8 << 20];
static size_t image_len;
static const char html[] = "<img src=\"https://example.com/cat.png\" alt=\"cat\">";
static const char mozurl[] = "h\0t\0t\0p\0s\0:\0/\0/\0e\0x\0a\0m\0p\0l\0e\0.\0c\0o\0m\0";

static void global(void *d, struct wl_registry *r, uint32_t name, const char *iface, uint32_t v) {
  if (!strcmp(iface, "wl_seat") && !seat) seat = wl_registry_bind(r, name, &wl_seat_interface, 2);
  if (!strcmp(iface, "ext_data_control_manager_v1")) manager = wl_registry_bind(r, name, &ext_data_control_manager_v1_interface, 1);
}
static void global_remove(void *d, struct wl_registry *r, uint32_t name) {}
static const struct wl_registry_listener registry_listener = {global, global_remove};

static void on_send(void *d, struct ext_data_control_source_v1 *s, const char *mime, int32_t fd) {
  const char *buf = !strcmp(mime, "image/png") ? image : !strcmp(mime, "text/html") ? html : mozurl;
  size_t len = buf == image ? image_len : buf == html ? strlen(html) : sizeof mozurl - 1;
  fprintf(stderr, "source: served a read of %s\n", mime);
  if (fork() == 0) {
    fcntl(fd, F_SETFL, 0);
    for (size_t off = 0; off < len;) {
      ssize_t w = write(fd, buf + off, len - off);
      if (w <= 0) break;
      off += w;
    }
    _exit(0);
  }
  close(fd);
}
static void on_cancelled(void *d, struct ext_data_control_source_v1 *s) { exit(0); }
static const struct ext_data_control_source_v1_listener source_listener = {on_send, on_cancelled};

static void data_offer(void *d, struct ext_data_control_device_v1 *dev, struct ext_data_control_offer_v1 *o) {}
static void selection(void *d, struct ext_data_control_device_v1 *dev, struct ext_data_control_offer_v1 *o) {
  if (o) ext_data_control_offer_v1_destroy(o);
}
static void finished(void *d, struct ext_data_control_device_v1 *dev) { exit(1); }
static const struct ext_data_control_device_v1_listener device_listener = {data_offer, selection, finished, selection};

int main(int argc, char **argv) {
  signal(SIGCHLD, SIG_IGN);
  int fd = open(argv[1], O_RDONLY);
  image_len = read(fd, image, sizeof image);
  struct wl_display *dpy = wl_display_connect(NULL);
  wl_registry_add_listener(wl_display_get_registry(dpy), &registry_listener, NULL);
  wl_display_roundtrip(dpy);
  struct ext_data_control_source_v1 *src = ext_data_control_manager_v1_create_data_source(manager);
  ext_data_control_source_v1_add_listener(src, &source_listener, NULL);
  ext_data_control_source_v1_offer(src, "image/png");
  ext_data_control_source_v1_offer(src, "text/html");
  ext_data_control_source_v1_offer(src, "text/x-moz-url");
  struct ext_data_control_device_v1 *dev = ext_data_control_manager_v1_get_data_device(manager, seat);
  ext_data_control_device_v1_add_listener(dev, &device_listener, NULL);
  ext_data_control_device_v1_set_selection(dev, src);
  wl_display_roundtrip(dpy);
  printf("ready\n");
  fflush(stdout);
  while (wl_display_dispatch(dpy) >= 0) {}
  return 1;
}
```

